1	# Multi-store TikTok ad scrape via ziniao-cli (dynamic store list)
2	# Usage:
3	#   powershell -ExecutionPolicy Bypass -File .\scripts\run-multi-store.ps1
4	#   powershell -ExecutionPolicy Bypass -File .\scripts\run-multi-store.ps1 -DryRun true
5	#   powershell -ExecutionPolicy Bypass -File .\scripts\run-multi-store.ps1 -DryRun false
6	#   powershell -ExecutionPolicy Bypass -File .\scripts\run-multi-store.ps1 -ListOnly
7	#
8	# Requires: Ziniao client running + ziniao-cli doctor OK
9	# Config: config\stores.config.json
10	
11	param(
12	  [string]$ConfigPath = "",
13	  [switch]$ListOnly,
14	  # string so -File callers work (Nullable[bool] cannot bind "$true"/"$false" from -File)
15	  # omit / empty => use config.options.dryRun; true|1|yes / false|0|no
16	  [string]$DryRun = ""
17	)
18	
19	$ErrorActionPreference = 'Stop'
20	# ziniao-cli writes progress to stderr; do not treat as terminating
21	$PSNativeCommandUseErrorActionPreference = $false
22	$root = Split-Path $PSScriptRoot -Parent
23	if (-not $ConfigPath) {
24	  $ConfigPath = Join-Path $root 'config\stores.config.json'
25	}
26	$scrapeJsPath = Join-Path $root 'scripts\scrape-ads-page.js'
27	$dateRangeJsPath = Join-Path $root 'scripts\set-date-range.js'
28	
29	if (-not (Test-Path $ConfigPath)) {
30	  throw "Missing config: $ConfigPath (copy config\stores.config.example.json)"
31	}
32	if (-not (Test-Path $scrapeJsPath)) {
33	  throw "Missing scrape script: $scrapeJsPath"
34	}
35	if (-not (Test-Path $dateRangeJsPath)) {
36	  throw "Missing date-range script: $dateRangeJsPath"
37	}
38	
39	$cfg = Get-Content $ConfigPath -Raw -Encoding UTF8 | ConvertFrom-Json
40	$scrapeJs = Get-Content $scrapeJsPath -Raw -Encoding UTF8
41	$dateRangeJsTemplate = Get-Content $dateRangeJsPath -Raw -Encoding UTF8
42	$analysisLib = Join-Path $PSScriptRoot 'daily-analysis.ps1'
43	if (Test-Path $analysisLib) { . $analysisLib }
44	$qingquanLib = Join-Path $PSScriptRoot 'qingquan-client.ps1'
45	if (Test-Path $qingquanLib) { . $qingquanLib }
46	
47	# Always create logs/ first so early failures (Bridge down, ListOnly, throw) still leave a file
48	$script:logsDir = Join-Path $root 'logs'
49	New-Item -ItemType Directory -Force -Path $script:logsDir | Out-Null
50	$script:runStamp = Get-Date -Format 'yyyyMMdd-HHmmss'
51	$script:runLogFile = Join-Path $script:logsDir ("multi-store-run-{0}.log" -f $script:runStamp)
52	$script:runMode = if ($ListOnly) { 'listOnly' } else { 'scrape' }
53	
54	function Write-RunLog([string]$msg) {
55	  $line = "[{0}] {1}" -f (Get-Date -Format 'yyyy-MM-dd HH:mm:ss'), $msg
56	  try {
57	    Add-Content -LiteralPath $script:runLogFile -Value $line -Encoding UTF8
58	  } catch { }
59	}
60	
61	function Write-Step([string]$msg) {
62	  $line = "[{0}] {1}" -f (Get-Date -Format 'HH:mm:ss'), $msg
63	  Write-Host $line
64	  Write-RunLog $msg
65	}
66	
67	function Save-FailArtifact([string]$errorText, [hashtable]$extra = @{}) {
68	  $obj = [ordered]@{
69	    ok        = $false
70	    mode      = $script:runMode
71	    time      = (Get-Date).ToString('o')
72	    error     = $errorText
73	    runLog    = $script:runLogFile
74	    config    = $ConfigPath
75	    root      = $root
76	  }
77	  foreach ($k in $extra.Keys) { $obj[$k] = $extra[$k] }
78	  $failPath = Join-Path $script:logsDir ("multi-store-fail-{0}.json" -f $script:runStamp)
79	  try {
80	    ($obj | ConvertTo-Json -Depth 8) | Set-Content -LiteralPath $failPath -Encoding UTF8
81	    Write-Step ("fail log: {0}" -f $failPath)
82	  } catch {
83	    Write-Host ("[warn] could not write fail log: {0}" -f $_)
84	  }
85	  Write-Step ("run log: {0}" -f $script:runLogFile)
86	  return $failPath
87	}
88	
89	Write-Step ("===== multi-store START mode={0} =====" -f $script:runMode)
90	Write-Step ("root={0}" -f $root)
91	Write-Step ("config={0}" -f $ConfigPath)
92	Write-Step ("runLog={0}" -f $script:runLogFile)
93	
94	trap {
95	  $errText = ($_ | Out-String).Trim()
96	  try {
97	    Write-Host ""
98	    Write-Host "===== FATAL (see logs/) =====" -ForegroundColor Red
99	    Write-Host $errText
100	    if ($errText -match '9481|Bridge|store list failed|无法连接|network') {
101	      Write-Host ""
102	      Write-Host "HINT: 紫鸟 Bridge 不可用。请打开并登录「紫鸟」桌面客户端后重试。" -ForegroundColor Yellow
103	      Write-Host "      仅安装 Node/ziniao-cli 不够；本机客户端须在线 (127.0.0.1:9481)。" -ForegroundColor Yellow
104	    }
105	    Save-FailArtifact $errText | Out-Null
106	  } catch { }
107	  break
108	}
