110	# 业务日按广告后台时区（英区 = 伦敦），不要用中国本地日历日。
111	# 中国早上 8 点 ≈ 英国 0 点：按本地算「今天」会抓到英国日刚开始的半截数据。
112	function Resolve-BizTimeZone([string]$preferred) {
113	  $candidates = @()
114	  if ($preferred) { $candidates += $preferred }
115	  # Windows 时区 ID：GMT Standard Time = 伦敦（含夏令时）
116	  $candidates += @('GMT Standard Time', 'Greenwich Standard Time', 'UTC')
117	  foreach ($id in $candidates) {
118	    try {
119	      return [TimeZoneInfo]::FindSystemTimeZoneById($id)
120	    } catch { }
121	  }
122	  return [TimeZoneInfo]::Utc
123	}
124	
125	function Get-BizNow([TimeZoneInfo]$tz) {
126	  return [TimeZoneInfo]::ConvertTimeFromUtc([datetime]::UtcNow, $tz)
127	}
128	
129	function Get-BizDate([string]$mode, [TimeZoneInfo]$tz) {
130	  if (-not $tz) { $tz = Resolve-BizTimeZone 'GMT Standard Time' }
131	  $d = Get-BizNow $tz
132	  if ($mode -eq 'yesterday') { $d = $d.AddDays(-1) }
133	  return $d.ToString('yyyy-MM-dd')
134	}
