136	# 计划开关归一：on | off | unknown
137	function Normalize-PlanStatus($raw) {
138	  if ($null -eq $raw) { return 'unknown' }
139	  $s = ([string]$raw).Trim().ToLowerInvariant()
140	  if ([string]::IsNullOrWhiteSpace($s)) { return 'unknown' }
141	  if ($s -match '^(on|1|true|open|enable|enabled|active|running|投放中|开启|开)$') { return 'on' }
142	  if ($s -match '^(off|0|false|close|closed|disable|disabled|paused|inactive|已关闭|关闭|关|暂停)$') { return 'off' }
143	  return 'unknown'
144	}
145	
146	# 策略 C：已关闭 且 花费=0 且 销售额=0 → 跳过；有花费/销售额的关闭计划仍保留
147	function Test-SkipZeroDisabledCampaign($row) {
148	  $ps = Normalize-PlanStatus $row.planStatus
149	  if ($ps -ne 'off') { return $false }
150	  $spend = 0.0
151	  if ($null -ne $row.spend) { $spend = [double]$row.spend }
152	  $revenue = 0.0
153	  if ($null -ne $row.revenue) { $revenue = [double]$row.revenue }
154	  return ($spend -eq 0 -and $revenue -eq 0)
155	}
