157	function Test-StoreFilter($store, $filter) {
158	  if ($filter.includeStoreIds -and @($filter.includeStoreIds).Count -gt 0) {
159	    if ($store.storeId -notin @($filter.includeStoreIds)) { return $false }
160	  }
161	  if ($filter.excludeStoreIds -and ($store.storeId -in @($filter.excludeStoreIds))) {
162	    return $false
163	  }
164	  if ($filter.requireIp -eq $true) {
165	    if (-not $store.ip -or [string]::IsNullOrWhiteSpace([string]$store.ip)) { return $false }
166	  }
167	  $platform = [string]$store.platformName
168	  $name = [string]$store.storeName
169	  if ($filter.platformContains -and @($filter.platformContains).Count -gt 0) {
170	    $ok = $false
171	    foreach ($p in @($filter.platformContains)) {
172	      if ($platform -like "*$p*") { $ok = $true; break }
173	    }
174	    if (-not $ok) { return $false }
175	  }
176	  if ($filter.nameContains -and @($filter.nameContains).Count -gt 0) {
177	    $ok = $false
178	    foreach ($p in @($filter.nameContains)) {
179	      if ($name -like "*$p*") { $ok = $true; break }
180	    }
181	    if (-not $ok) { return $false }
182	  }
183	  if ($filter.nameExclude) {
184	    foreach ($p in @($filter.nameExclude)) {
185	      if ($name -like "*$p*") { return $false }
186	    }
187	  }
188	  return $true
189	}
