191	function Get-AdsUrl($store, $adsUrlCfg) {
192	  $platform = [string]$store.platformName
193	  if ($adsUrlCfg.byPlatform) {
194	    foreach ($p in $adsUrlCfg.byPlatform.PSObject.Properties) {
195	      if ($p.Name -eq $platform) { return [string]$p.Value }
196	    }
197	    foreach ($p in $adsUrlCfg.byPlatform.PSObject.Properties) {
198	      if ($platform -like "*$($p.Name)*") { return [string]$p.Value }
199	    }
200	  }
201	  return [string]$adsUrlCfg.default
202	}
203	
204	function Get-DisplayName($store, $map) {
205	  $name = [string]$store.storeName
206	  if ($map) {
207	    foreach ($p in $map.PSObject.Properties) {
208	      if ($p.Name -eq $name) { return [string]$p.Value }
209	    }
210	    foreach ($p in $map.PSObject.Properties) {
211	      if ($name -like "*$($p.Name)*" -or $p.Name -like "*$name*") {
212	        return [string]$p.Value
213	      }
214	    }
215	  }
216	  return $name
217	}
