219	function Maximize-ZiniaoBrowserWindows {
220	  # 紫鸟开店默认常是小窗；Win32 最大化有助于广告表完整渲染
221	  $code = @'
222	using System;
223	using System.Text;
224	using System.Collections.Generic;
225	using System.Runtime.InteropServices;
226	
227	public class ZiniaoWinMax {
228	  public delegate bool EnumProc(IntPtr hWnd, IntPtr lParam);
229	  [DllImport("user32.dll")] public static extern bool EnumWindows(EnumProc lpEnumFunc, IntPtr lParam);
230	  [DllImport("user32.dll")] public static extern bool IsWindowVisible(IntPtr hWnd);
231	  [DllImport("user32.dll", CharSet = CharSet.Unicode)] public static extern int GetWindowText(IntPtr hWnd, StringBuilder lpString, int nMaxCount);
232	  [DllImport("user32.dll", CharSet = CharSet.Unicode)] public static extern int GetClassName(IntPtr hWnd, StringBuilder lpClassName, int nMaxCount);
233	  [DllImport("user32.dll")] public static extern bool ShowWindow(IntPtr hWnd, int nCmdShow);
234	  const int SW_MAXIMIZE = 3;
235	
236	  public static int MaximizeMatching() {
237	    int n = 0;
238	    EnumWindows((hWnd, l) => {
239	      if (!IsWindowVisible(hWnd)) return true;
240	      var title = new StringBuilder(512);
241	      var cls = new StringBuilder(256);
242	      GetWindowText(hWnd, title, title.Capacity);
243	      GetClassName(hWnd, cls, cls.Capacity);
244	      string t = title.ToString();
245	      string c = cls.ToString();
246	      // 紫鸟店铺窗多为 Chromium；标题常含 TikTok / seller / 店铺名
247	      bool chrome = c.IndexOf("Chrome_WidgetWin", StringComparison.OrdinalIgnoreCase) >= 0
248	                 || c.IndexOf("Chrome_WidgetWin_1", StringComparison.OrdinalIgnoreCase) >= 0;
249	      bool hint = t.IndexOf("TikTok", StringComparison.OrdinalIgnoreCase) >= 0
250	               || t.IndexOf("tiktok", StringComparison.OrdinalIgnoreCase) >= 0
251	               || t.IndexOf("seller", StringComparison.OrdinalIgnoreCase) >= 0
252	               || t.IndexOf("紫鸟", StringComparison.OrdinalIgnoreCase) >= 0
253	               || t.IndexOf("Ziniao", StringComparison.OrdinalIgnoreCase) >= 0
254	               || t.IndexOf("ads-creation", StringComparison.OrdinalIgnoreCase) >= 0;
255	      if (chrome && (hint || t.Length > 0)) {
256	        // 避免把用户普通 Chrome 主页误最大化：要求标题像店铺/广告或非空且 chrome
257	        if (hint || t.IndexOf("Shop", StringComparison.OrdinalIgnoreCase) >= 0) {
258	          ShowWindow(hWnd, SW_MAXIMIZE);
259	          n++;
260	        }
261	      }
262	      return true;
263	    }, IntPtr.Zero);
264	    return n;
265	  }
266	}
267	'@
268	  if (-not ('ZiniaoWinMax' -as [type])) {
269	    Add-Type -TypeDefinition $code -ErrorAction Stop
270	  }
271	  return [ZiniaoWinMax]::MaximizeMatching()
272	}
