274	function Get-CurrencyConfig($cfg) {
275	  # 与 TikTok 广告后台一致：广告花费 / 销售额统一按美金(USD) 落库与写飞书
276	  $target = 'USD'
277	  $pageDefault = 'USD'
278	  $convert = $true
279	  $rates = @{
280	    USD = 1.0
281	    GBP = 1.27
282	    EUR = 1.08
283	    CNY = 0.14
284	  }
285	  if ($cfg.currency) {
286	    if ($cfg.currency.target) { $target = ([string]$cfg.currency.target).ToUpperInvariant() }
287	    if ($cfg.currency.pageDefault) { $pageDefault = ([string]$cfg.currency.pageDefault).ToUpperInvariant() }
288	    if ($null -ne $cfg.currency.convert) { $convert = [bool]$cfg.currency.convert }
289	    if ($cfg.currency.ratesToUsd) {
290	      foreach ($p in $cfg.currency.ratesToUsd.PSObject.Properties) {
291	        try { $rates[$p.Name.ToUpperInvariant()] = [double]$p.Value } catch { }
292	      }
293	    }
294	  }
295	  return [pscustomobject]@{
296	    target      = $target
297	    pageDefault = $pageDefault
298	    convert     = $convert
299	    ratesToUsd  = $rates
300	  }
301	}
302	
303	function Convert-MoneyToTarget {
304	  param(
305	    [double]$Amount,
306	    [string]$FromCurrency,
307	    [string]$TargetCurrency,
308	    $RatesToUsd
309	  )
310	  $from = if ($FromCurrency) { $FromCurrency.ToUpperInvariant() } else { 'USD' }
311	  $to = if ($TargetCurrency) { $TargetCurrency.ToUpperInvariant() } else { 'USD' }
312	  if ($from -eq $to) { return [math]::Round($Amount, 2) }
313	  $rateFrom = 1.0
314	  $rateTo = 1.0
315	  if ($RatesToUsd.ContainsKey($from)) { $rateFrom = [double]$RatesToUsd[$from] }
316	  if ($RatesToUsd.ContainsKey($to)) { $rateTo = [double]$RatesToUsd[$to] }
317	  if ($rateFrom -le 0 -or $rateTo -le 0) { return [math]::Round($Amount, 2) }
318	  # ratesToUsd: 1 unit of currency → USD；先转 USD 再转目标币
319	  $usd = $Amount * $rateFrom
320	  return [math]::Round($usd / $rateTo, 2)
321	}
