323	function Get-FeishuToken($appId, $appSecret) {
324	  $body = @{ app_id = $appId; app_secret = $appSecret } | ConvertTo-Json
325	  $r = Invoke-RestMethod -Method POST -Uri 'https://open.feishu.cn/open-apis/auth/v3/tenant_access_token/internal' `
326	    -ContentType 'application/json; charset=utf-8' -Body $body
327	  if ($r.code -ne 0) { throw "Feishu token failed: $($r.msg)" }
328	  return $r.tenant_access_token
329	}
330	
331	function Write-FeishuRows($feishu, $rows, $dryRun) {
332	  if ($dryRun) {
333	    Write-Step ("  [dry-run] skip Feishu write, rows={0}" -f $rows.Count)
334	    return @{ written = 0; dryRun = $true }
335	  }
336	  if (-not $rows.Count) { return @{ written = 0; dryRun = $false } }
337	
338	  $token = Get-FeishuToken $feishu.appId $feishu.appSecret
339	  $url = "https://open.feishu.cn/open-apis/bitable/v1/apps/$($feishu.appToken)/tables/$($feishu.tableId)/records/batch_create"
340	  $fieldsUrl = "https://open.feishu.cn/open-apis/bitable/v1/apps/$($feishu.appToken)/tables/$($feishu.tableId)/fields?page_size=100"
341	  $fieldList = Invoke-RestMethod -Method GET -Uri $fieldsUrl -Headers @{ Authorization = "Bearer $token" }
342	  $names = @($fieldList.data.items | ForEach-Object { $_.field_name })
343	
344	  function Pick-Name([string[]]$aliases) {
345	    foreach ($a in $aliases) { if ($names -contains $a) { return $a } }
346	    return $null
347	  }
348	
349	  # UTF-8 field names (same as extension BITABLE_FIELDS)
350	  $utf8 = [System.Text.Encoding]::UTF8
351	  $A_DATE = @($utf8.GetString([byte[]](0xE6,0x97,0xA5,0xE6,0x9C,0x9F)))
352	  $A_STORE = @($utf8.GetString([byte[]](0xE5,0xBA,0x97,0xE9,0x93,0xBA)))
353	  $A_STORE_ID = @($utf8.GetString([byte[]](0xE5,0xBA,0x97,0xE9,0x93,0xBA,0x49,0x44)))
354	  $A_CAMPAIGN = @(
355	    $utf8.GetString([byte[]](0xE5,0x93,0x81,0xE5,0x90,0x8D)),
356	    $utf8.GetString([byte[]](0xE5,0xB9,0xBF,0xE5,0x91,0x8A,0xE7,0xB3,0xBB,0xE5,0x88,0x97,0xE5,0x90,0x8D,0xE7,0xA7,0xB0))
357	  )
358	  $A_SPEND = @(
359	    $utf8.GetString([byte[]](0xE5,0xB9,0xBF,0xE5,0x91,0x8A,0xE8,0x8A,0xB1,0xE8,0xB4,0xB9)),
360	    $utf8.GetString([byte[]](0xE6,0x88,0x90,0xE6,0x9C,0xAC))
361	  )
362	  $A_ORDERS = @($utf8.GetString([byte[]](0xE9,0x94,0x80,0xE9,0x87,0x8F)))
363	  $A_ROI = @('ROI')
364	  $A_REVENUE = @(
365	    $utf8.GetString([byte[]](0xE9,0x94,0x80,0xE5,0x94,0xAE,0xE9,0xA2,0x9D)),
366	    $utf8.GetString([byte[]](0xE6,0x80,0xBB,0xE6,0x94,0xB6,0xE5,0x85,0xA5))
367	  )
368	  $A_SCRAPED = @($utf8.GetString([byte[]](0xE6,0x8A,0x93,0xE5,0x8F,0x96,0xE6,0x97,0xB6,0xE9,0x97,0xB4)))
369	  $A_URL = @($utf8.GetString([byte[]](0xE6,0x95,0xB0,0xE6,0x8D,0xAE,0xE6,0xBA,0x90,0x55,0x52,0x4C)))
370	  $A_STATUS = @($utf8.GetString([byte[]](0xE7,0x8A,0xB6,0xE6,0x80,0x81)))
371	  # 计划状态 / 投放状态 / 开关
372	  $A_PLAN = @(
373	    $utf8.GetString([byte[]](0xE8,0xAE,0xA1,0xE5,0x88,0x92,0xE7,0x8A,0xB6,0xE6,0x80,0x81)),
374	    $utf8.GetString([byte[]](0xE6,0x8A,0x95,0xE6,0x94,0xBE,0xE7,0x8A,0xB6,0xE6,0x80,0x81)),
375	    $utf8.GetString([byte[]](0xE5,0xBC,0x80,0xE5,0x85,0xB3))
376	  )
377	
378	  $fn = @{
379	    date       = Pick-Name $A_DATE
380	    store      = Pick-Name $A_STORE
381	    storeId    = Pick-Name $A_STORE_ID
382	    campaign   = Pick-Name $A_CAMPAIGN
383	    spend      = Pick-Name $A_SPEND
384	    orders     = Pick-Name $A_ORDERS
385	    roi        = Pick-Name $A_ROI
386	    revenue    = Pick-Name $A_REVENUE
387	    scrapedAt  = Pick-Name $A_SCRAPED
388	    sourceUrl  = Pick-Name $A_URL
389	    status     = Pick-Name $A_STATUS
390	    planStatus = Pick-Name $A_PLAN
391	  }
392	
393	  if (-not $fn.campaign -or -not $fn.store) {
394	    throw ("Feishu fields incomplete. Have: {0}" -f ($names -join ', '))
395	  }
396	
397	  $records = @()
398	  foreach ($row in $rows) {
399	    $fields = @{}
400	    if ($fn.date) {
401	      $dt = [DateTime]::ParseExact($row.date, 'yyyy-MM-dd', $null)
402	      $fields[$fn.date] = [DateTimeOffset]::new($dt).ToUnixTimeMilliseconds()
403	    }
404	    if ($fn.store) { $fields[$fn.store] = $row.store }
405	    if ($fn.storeId) { $fields[$fn.storeId] = $row.storeId }
406	    if ($fn.campaign) { $fields[$fn.campaign] = $row.campaign }
407	    if ($fn.spend) { $fields[$fn.spend] = [double]$row.spend }
408	    if ($fn.orders) { $fields[$fn.orders] = [double]$row.orders }
409	    if ($fn.roi) { $fields[$fn.roi] = [double]$row.roi }
410	    if ($fn.revenue) { $fields[$fn.revenue] = [double]$row.revenue }
411	    if ($fn.scrapedAt) { $fields[$fn.scrapedAt] = [DateTimeOffset]::UtcNow.ToUnixTimeMilliseconds() }
412	    if ($fn.sourceUrl) { $fields[$fn.sourceUrl] = $row.sourceUrl }
413	    if ($fn.status) { $fields[$fn.status] = $row.status }
414	    if ($fn.planStatus -and $row.planStatus) {
415	      $ps = [string]$row.planStatus
416	      # 飞书展示：on/off/unknown → 投放中/已关闭/未知
417	      if ($ps -eq 'on') { $ps = $utf8.GetString([byte[]](0xE6,0x8A,0x95,0xE6,0x94,0xBE,0xE4,0xB8,0xAD)) }
418	      elseif ($ps -eq 'off') { $ps = $utf8.GetString([byte[]](0xE5,0xB7,0xB2,0xE5,0x85,0xB3,0xE9,0x97,0xAD)) }
419	      elseif ($ps -eq 'unknown') { $ps = $utf8.GetString([byte[]](0xE6,0x9C,0xAA,0xE7,0x9F,0xA5)) }
420	      $fields[$fn.planStatus] = $ps
421	    }
422	    $records += @{ fields = $fields }
423	  }
424	
425	  $bodyBytes = [System.Text.Encoding]::UTF8.GetBytes((@{ records = $records } | ConvertTo-Json -Depth 8 -Compress))
426	  $resp = Invoke-RestMethod -Method POST -Uri $url -Headers @{ Authorization = "Bearer $token" } `
427	    -ContentType 'application/json; charset=utf-8' -Body $bodyBytes
428	  if ($resp.code -ne 0) {
429	    throw ("Feishu write failed: code={0} msg={1}" -f $resp.code, $resp.msg)
