435	function ConvertTo-ProcessArgument([string]$arg) {
436	  # CommandLineToArgvW-style quoting for ProcessStartInfo.Arguments
437	  if ($null -eq $arg) { return '""' }
438	  if ($arg -notmatch '[\s"]') { return $arg }
439	  $bs = [char]0x5C
440	  $sb = New-Object System.Text.StringBuilder
441	  [void]$sb.Append([char]0x22)
442	  $backslashes = 0
443	  foreach ($ch in $arg.ToCharArray()) {
444	    if ($ch -eq $bs) {
445	      $backslashes++
446	      continue
447	    }
448	    if ($ch -eq [char]0x22) {
449	      [void]$sb.Append($bs, $backslashes * 2 + 1)
450	      [void]$sb.Append([char]0x22)
451	      $backslashes = 0
452	      continue
453	    }
454	    if ($backslashes -gt 0) {
455	      [void]$sb.Append($bs, $backslashes)
456	      $backslashes = 0
457	    }
458	    [void]$sb.Append($ch)
459	  }
460	  if ($backslashes -gt 0) { [void]$sb.Append($bs, $backslashes * 2) }
461	  [void]$sb.Append([char]0x22)
462	  return $sb.ToString()
463	}
