498	function Invoke-Ziniao([string[]]$CliArgs) {
499	  # UTF-8 capture via ProcessStartInfo. npm ziniao-cli is .ps1 — call node run.js instead.
500	  Initialize-ZiniaoCli
501	  $utf8 = [System.Text.UTF8Encoding]::new($false)
502	
503	  $allArgs = @($script:ZiniaoRunJs) + @($CliArgs)
504	  $argLine = ($allArgs | ForEach-Object { ConvertTo-ProcessArgument ([string]$_) }) -join ' '
505	
506	  $psi = New-Object System.Diagnostics.ProcessStartInfo
507	  $psi.FileName = $script:ZiniaoNode
508	  $psi.Arguments = $argLine
509	  $psi.UseShellExecute = $false
510	  $psi.RedirectStandardOutput = $true
511	  $psi.RedirectStandardError = $true
512	  $psi.CreateNoWindow = $true
513	  $psi.StandardOutputEncoding = $utf8
514	  $psi.StandardErrorEncoding = $utf8
515	
516	  $p = New-Object System.Diagnostics.Process
517	  $p.StartInfo = $psi
518	  try {
519	    [void]$p.Start()
520	  } catch {
521	    throw "Failed to start ziniao (node): $($_.Exception.Message)"
522	  }
523	  $stdout = $p.StandardOutput.ReadToEnd()
524	  $stderr = $p.StandardError.ReadToEnd()
525	  $p.WaitForExit()
526	
527	  $parts = @()
528	  if (-not [string]::IsNullOrEmpty($stdout)) { $parts += $stdout.TrimEnd("`r", "`n") }
529	  if (-not [string]::IsNullOrEmpty($stderr)) { $parts += $stderr.TrimEnd("`r", "`n") }
530	  return ($parts -join "`n")
531	}
