591	function Get-PageExecJsonPayload([string]$execOut, [scriptblock]$shapeTest) {
592	  # ziniao-cli page exec shapes seen in the wild:
593	  #   { ok, data: { ok, storeId, data: { exceptionDetails, result: "<json string>", targetId } } }
594	  #   { ok, data: { data: { result: { type, value: "<json string>" } } } }  (raw CDP)
595	  function Convert-MaybeJsonString($v) {
596	    if ($v -is [string]) {
597	      $inner = ConvertFrom-JsonSafe $v
598	      if ($null -ne $inner -and (& $shapeTest $inner)) { return $inner }
599	      return $null
600	    }
601	    if (& $shapeTest $v) { return $v }
602	    return $null
603	  }
604	
605	  $root = ConvertFrom-JsonSafe $execOut
606	  if ($null -ne $root) {
607	    $candidates = @(
608	      $root
609	      $(if ($root.data) { $root.data } else { $null })
610	      $(if ($root.data -and $root.data.data) { $root.data.data } else { $null })
611	      $(if ($root.data -and $root.data.data -and $root.data.data.result) { $root.data.data.result } else { $null })
612	      $(if ($root.data -and $root.data.result) { $root.data.result } else { $null })
613	      $(if ($root.result) { $root.result } else { $null })
614	    )
615	    foreach ($c in $candidates) {
616	      if ($null -eq $c) { continue }
617	      if ($c -is [string]) {
618	        $hit = Convert-MaybeJsonString $c
619	        if ($hit) { return $hit }
620	        continue
621	      }
622	      if ($c.PSObject.Properties.Name -contains 'value') {
623	        $hit = Convert-MaybeJsonString $c.value
624	        if ($hit) { return $hit }
625	      }
626	      if ($c.PSObject.Properties.Name -contains 'result') {
627	        $hit = Convert-MaybeJsonString $c.result
628	        if ($hit) { return $hit }
629	        if ($c.result -and ($c.result.PSObject.Properties.Name -contains 'value')) {
630	          $hit = Convert-MaybeJsonString $c.result.value
631	          if ($hit) { return $hit }
632	        }
633	      }
634	      $hit = Convert-MaybeJsonString $c
635	      if ($hit) { return $hit }
636	    }
637	  }
638	
639	  if ($execOut -match '(?s)(\{\s*"ok"\s*:\s*(?:true|false)[\s\S]{0,4000}\})') {
640	    $m = ConvertFrom-JsonSafe $Matches[1]
641	    if ($m -and (& $shapeTest $m)) { return $m }
642	  }
643	  return $null
644	}
