646	function Get-DateRangePayload([string]$execOut) {
647	  $shape = {
648	    param($o)
649	    if ($null -eq $o) { return $false }
650	    if ($o -is [string]) { return $false }
651	    $names = @($o.PSObject.Properties.Name)
652	    return ($names -contains 'ok') -and (
653	      ($names -contains 'mode') -or ($names -contains 'action') -or
654	      ($names -contains 'before') -or ($names -contains 'after') -or
655	      ($names -contains 'clicked') -or ($names -contains 'matched') -or
656	      ($names -contains 'range') -or ($names -contains 'panelOpen')
657	    )
658	  }
659	  return Get-PageExecJsonPayload $execOut $shape
660	}
