662	function Get-ScrapePayload([string]$execOut) {
663	  # Our scraper returns JSON.stringify({ ok, rows, source, url, error })
664	  function Test-ScrapeShape($o) {
665	    if ($null -eq $o) { return $false }
666	    if ($o -is [string]) { return $false }
667	    $names = @($o.PSObject.Properties.Name)
668	    return ($names -contains 'rows') -or (($names -contains 'ok') -and ($names -contains 'source' -or $names -contains 'error'))
669	  }
670	  function Convert-MaybeJsonString($v) {
671	    if ($v -is [string]) {
672	      $inner = ConvertFrom-JsonSafe $v
673	      if (Test-ScrapeShape $inner) { return $inner }
674	      return $null
675	    }
676	    if (Test-ScrapeShape $v) { return $v }
677	    if ($v -and ($v.PSObject.Properties.Name -contains 'value')) {
678	      return Convert-MaybeJsonString $v.value
679	    }
680	    return $null
681	  }
682	
683	  $root = ConvertFrom-JsonSafe $execOut
684	  if (-not $root) {
685	    if ($execOut -match '(?s)(\{\s*"ok"\s*:\s*(?:true|false)\s*,\s*"source"[\s\S]*?"rows"\s*:\s*\[[\s\S]*?\})') {
686	      return (ConvertFrom-JsonSafe $Matches[1])
687	    }
688	    return $null
689	  }
690	
691	  # Walk common nest paths first
692	  $paths = @(
693	    { param($r) $r },
694	    { param($r) $r.data },
695	    { param($r) $r.data.data },
696	    { param($r) $r.data.result },
697	    { param($r) $r.data.data.result },
698	    { param($r) $r.data.data.result.value },
699	    { param($r) $r.result },
700	    { param($r) $r.result.value }
701	  )
702	  foreach ($get in $paths) {
703	    try {
704	      $node = & $get $root
705	    } catch { continue }
706	    if ($null -eq $node) { continue }
707	
708	    # exception on this node?
709	    if ($node -isnot [string] -and $node.PSObject.Properties.Name -contains 'exceptionDetails' -and $node.exceptionDetails) {
710	      $ex = $node.exceptionDetails
711	      $msg = if ($ex.exception -and $ex.exception.description) { [string]$ex.exception.description }
712	             elseif ($ex.text) { [string]$ex.text }
713	             else { 'page exec exception' }
714	      return [pscustomobject]@{ ok = $false; rows = @(); error = $msg; source = 'exception' }
715	    }
716	
717	    $parsed = Convert-MaybeJsonString $node
718	    if ($parsed) { return $parsed }
719	
720	    # node has .result string/object
721	    if ($node -isnot [string] -and $node.PSObject.Properties.Name -contains 'result') {
722	      $parsed = Convert-MaybeJsonString $node.result
723	      if ($parsed) { return $parsed }
724	    }
725	  }
726	
727	  # Fallback: unescaped scrape JSON embedded in the CLI text
728	  if ($execOut -match '(?s)(\{\s*"ok"\s*:\s*(?:true|false)\s*,\s*"source"\s*:[\s\S]*?"rows"\s*:\s*\[[\s\S]*?\})') {
729	    $inner = ConvertFrom-JsonSafe $Matches[1]
730	    if ($inner) { return $inner }
731	  }
732	  # Escaped form inside result:"{...}"
733	  if ($execOut -match '"result"\s*:\s*"(\{\\"ok\\".+?\})"') {
734	    $unescaped = $Matches[1] -replace '\\"', '"' -replace '\\\\', '\'
735	    $inner = ConvertFrom-JsonSafe $unescaped
736	    if ($inner) { return $inner }
737	  }
738	
739	  return [pscustomobject]@{
740	    ok         = $false
741	    rows       = @()
742	    error      = 'unrecognized page exec payload'
743	    source     = 'parse'
744	    rawPreview = if ($execOut.Length -gt 400) { $execOut.Substring(0, 400) } else { $execOut }
745	  }
746	}
